 with page.expect_download() as dl:page.locator('#save-gift').click()
 gift=dl.value;gift.save_as(str(P/'test-invitation.html'));check('Gift file contains arrival marker','id="gift-arrival"' in (P/'test-invitation.html').read_text())
 g=c.new_page();g.on('pageerror',lambda e:errors.append('Gift: '+str(e)));g.set_content((P/'test-invitation.html').read_text(),wait_until='load');g.wait_for_timeout(500)
 check('Recipient gets the promised greeting','They sent' in g.locator('#wonder-title').inner_text());g.close()
 # Test local-memory save/reload under an explicit simulated Storage shim.
 store={};st=c.new_page();shim="""<script>window.fakeStorage={};Object.defineProperty(window,'localStorage',{value:{getItem:k=>window.fakeStorage[k]||null,setItem:(k,v)=>window.fakeStorage[k]=v,removeItem:k=>delete window.fakeStorage[k]}});</script>"""
 st.set_content(HTML.replace('<body data-view=',shim+'<body data-view='),wait_until='load');st.wait_for_timeout(300);st.evaluate('session.returned=true;session.discovered=true;OutOfPanel.switchView("play");OutOfPanel.newLocalGame();OutOfPanel.place(2,3);save()');stored=st.evaluate('fakeStorage["hyperspace-out-of-panel-v4"]');parsed=json.loads(stored);check('Saved state includes story and board',parsed['returned'] and parsed['discovered'] and parsed['game']['moves']==[[2,3]],'Simulated storage; browser restricts local storage at about:blank.')
