 page.emulate_media(reduced_motion='reduce');page.set_viewport_size({'width':390,'height':844});page.evaluate('OutOfPanel.switchView("object")');page.wait_for_timeout(120);y0=page.evaluate('coin.yaw');page.locator('#spin-object').click();page.wait_for_timeout(90);check('Reduced motion makes discrete turns',abs(page.evaluate('coin.yaw')-y0-math.pi)<.002)
 page.locator('#look-inside').click();page.wait_for_timeout(150);im1=page.locator('#world-canvas').screenshot();page.wait_for_timeout(150);im2=page.locator('#world-canvas').screenshot();check('Reduced motion keeps world still',im1==im2)
