report={'release':'0.4.0','environment':'Chromium, software 3D fallback; inline portable build at about:blank; emulated viewport sizes. No Safari or physical device/GPU test. Storage persistence uses an explicit shim.','passed':sum(r['pass'] for r in results),'failed':sum(not r['pass'] for r in results),'tests':results,'errors':errors}
